/* @autogenerated */
import { Component, inject } from '@angular/core';
import { OauthClient } from 'app/features/access/oauth-client/model/oauth-client.model';
import { OauthClientRepository } from 'app/features/access/oauth-client/repository/oauth-client-repository.service';
import { ConfirmSelectionAction } from 'app/shared/toolkit/action/confirm-selection-action';

@Component({ selector: 'oauth-client-view-disable-selection-action', standalone: false, template: '' })
export class OauthClientViewDisableSelectionActionComponent extends ConfirmSelectionAction<OauthClient> {
  readonly name = 'disableSelection';
  protected readonly scope = 'access/oauth-client';
  protected readonly repository = inject(OauthClientRepository);

  protected override appliesTo(items: OauthClient[]) {
    return items.every((item) => item.enabled !== false);
  }

  protected runSelection(items: OauthClient[]) {
    return this.repository.disableSelection({ uids: items.map((item) => item.uid) });
  }
}
